head.script:
/* ★Wcraft guide★    
스크립트 수작업 유의사항
*/


//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/common.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gIsurCd;
scwin.gImprRegDd;
scwin.gImprRegDd2;
scwin.gEmpNo = js_emp_no;
scwin.file_flag = "N";
scwin.gCondStat = "I"; // 디폴트 Insert : 입력가능, Update : 수정가능
scwin.gGubun; //계획서 구분(01: 개선계획서, 02: 이행보고서)

scwin.vScrenID = 'ULDSTF35105.xml';
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.fn_SetCode = function() {
    //gIsurCd = frame.Provider("../").txb_isurcd.value;
    scwin.gIsurCd = $c.frame.path("../").scwin.gIsurCd;
    scwin.gImprRegDd = $c.frame.path("../").scwin.gImprRegDd;
    scwin.gImprRegDd2 = $c.frame.path("../").scwin.gImprRegDd2;
    //계획서 구분(01: 개선계획서, 02: 이행보고서)
    scwin.gGubun = $c.frame.path("../").gUploadGubun;
    $c.stf.setObjectValue(edt_reg_dd, $c.ut.cGetToday("yyyymmdd"));
    $c.stf.setObjectValue(txb_emp_nm, js_emp_nm);
};
scwin.fn_InitSearch = function() {
    if (scwin.gGubun == "01") {
        if (scwin.gIsurCd != "" && scwin.gImprRegDd != '') {
            //개선계획서 수정로직

            // 조회 후  수정처리 기능이므로
            scwin.gCondStat = "U";
            var url_file = "/PenaltyImposition.do?method=readPnltImprSchdlFile&inputMessageId=IMPRSCHDLFILE_INOUT" + "&outputMessageId=IMPRSCHDLFILE_INOUT" + "&ISUR_CD=" + scwin.gIsurCd + "&IMPR_REG_DD=" + scwin.gImprRegDd + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

            //  데이타 조회
            dts_imprschdl_info.DataID = encodeURI(url_file);
            dts_imprschdl_info.reset();
        }
    } else {
        if (scwin.gIsurCd != "" && scwin.gImprRegDd2 != '') {
            //이행보고서 수정로직

            // 조회 후  수정처리 기능이므로
            scwin.gCondStat = "U";
            var url_file = "/PenaltyImposition.do?method=readPnltImprPerfmDtlFile&inputMessageId=IMPRSCHDLFILE_INOUT" + "&outputMessageId=IMPRSCHDLFILE_INOUT" + "&ISUR_CD=" + scwin.gIsurCd + "&IMPR_REG_DD=" + scwin.gImprRegDd2 + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

            //  데이타 조회
            dts_imprschdl_info.DataID = encodeURI(url_file);
            dts_imprschdl_info.reset();
        }
    }
};
scwin.fn_save = function() {
    // 등록
    //초기화
    dts_file_save.removeAll();
    if (scwin.gIsurCd == "") {
        $c.win.alert("벌점입력화면에서 법인을 조회 후 등록가능합니다.");
        return;
    }
    if ($c.stf.getObjectValue(edt_publ_end_dd) == "") {
        $c.win.alert("배포종료일을 입력하세요.");
        edt_publ_end_dd.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_reg_dd) > $c.stf.getObjectValue(edt_publ_end_dd)) {
        $c.win.alert('배포종료일을 등록일보다 큰 일자로 입력하세요');
        edt_publ_end_dd.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_file_nm) == "") {
        $c.win.alert("첨부파일을  입력해주세요");
        inf_find.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_file_nm).length > 80) {
        $c.win.alert("첨부파일명 길이 80자리를 초과했습니다.");
        txb_file_nm.focus();
        return;
    }
    dts_file_save.insertRow();
    dts_file_save.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_file_save.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_file_save.setCellData(1, "PUBL_END_DD", $c.stf.getObjectValue(edt_publ_end_dd));

    //2015.10.26 이민철

    var vAnswer;
    var vmethod;
    if (scwin.gGubun == "01") {
        vAnswer = confirm('개선계획서를 저장 하시겠습니까?');
        vmethod = "registerImprSchdlFile";
    } else {
        vAnswer = confirm('이행보고서를 저장 하시겠습니까?');
        vmethod = "registerImprPerfmDtlFile";
    }
    if (vAnswer == true) {
        trs_Save.Action = "/PenaltyImposition.do?method=" + vmethod + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        trs_Save.KeyValue = "JSP(I:pInput=dts_file_save,I:pFile=dts_fileData)";
        trs_Save.Post();
    }
};
scwin.fn_update = function() {
    //  수정
    var vUpdateTp; // 수정형태 : 1=배포종료일만수정, 2=첨부파일도 수정

    //초기화
    dts_file_save.removeAll();
    if (scwin.gIsurCd == "") {
        $c.win.alert("벌점입력화면에서 법인을 조회 후 등록가능합니다.");
        return;
    }
    if ($c.stf.getObjectValue(edt_publ_end_dd) == "") {
        $c.win.alert("배포종료일을 입력하세요.");
        edt_publ_end_dd.focus();
        return;
    }
    if ($c.stf.getObjectValue(edt_reg_dd) > $c.stf.getObjectValue(edt_publ_end_dd)) {
        $c.win.alert('배포종료일을 등록일보다 큰 일자로 입력하세요');
        edt_publ_end_dd.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_file_nm) == "") {
        $c.win.alert("첨부파일을  입력해주세요");
        inf_find.focus();
        return;
    }
    if ($c.stf.getObjectValue(txb_file_nm).length > 80) {
        $c.win.alert("첨부파일명 길이 80자리를 초과했습니다.");
        txb_file_nm.focus();
        return;
    }

    // 첨부파일은 그대로 배포종료일만 수정한 경우
    if (dts_fileData.getCellData(1, "fileUrl") == '') {
        vUpdateTp = '1';
    } else {
        vUpdateTp = '2';
    }


    //2015.10.26 이민철

    var vAnswer;
    var vmethod;
    var vImprRegDd;
    if (scwin.gGubun == "01") {
        vAnswer = confirm('개선계획서를 수정 하시겠습니까?');
        vmethod = "modifyImprSchdlFile";
        vImprRegDd = scwin.gImprRegDd;
    } else {
        vAnswer = confirm('이행보고서를 수정 하시겠습니까?');
        vmethod = "modifyImprPerfmDtlFile";
        vImprRegDd = scwin.gImprRegDd2;
    }
    dts_file_save.insertRow();
    dts_file_save.setCellData(1, "ISUR_CD", scwin.gIsurCd);
    dts_file_save.setCellData(1, "IMPR_REG_DD", vImprRegDd);
    dts_file_save.setCellData(1, "EMP_NO", scwin.gEmpNo);
    dts_file_save.setCellData(1, "PUBL_END_DD", $c.stf.getObjectValue(edt_publ_end_dd));
    dts_file_save.setCellData(1, "UPDATE_TP", vUpdateTp);
    if (vAnswer == true) {
        trs_Save.Action = "/PenaltyImposition.do?method=" + vmethod + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_03;
        trs_Save.KeyValue = "JSP(I:pInput=dts_file_save,I:pFile=dts_fileData)";
        trs_Save.Post();
    }
};



//파일 다운로드
scwin.fn_filedown = function() {
    var vRegDd = dts_imprschdl_info.getCellData(1, "IMPR_REG_DD");
    var link = "/filedownload.do?REG_DD=" + vRegDd + "&ISUR_CD=" + scwin.gIsurCd + "&gubun=10" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_08;
    location.href = encodeURI(link);
};
scwin.inf_find_OnClick = function() {
    dts_fileData.setCellData(dts_fileData.getRowPosition(), "fileInfo", inf_find.getValue());
    txb_file_nm.setValue(inf_find.getValue());
    scwin.file_flag = "Y";
};
scwin.trs_Save_OnSuccess = async function() {
    $c.win.alert("등록 성공");
    $c.frame.path("../").fn_Search();
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    $c.win.alert("등록 실패");
    $c.win.alert(trs_Save.ErrorMsg);
    //alert(dts_C_All.ErrorMsg);

};
scwin.img_save_onclick = function() {
    if (scwin.gCondStat == "U") {
        scwin.fn_update();
    } else {
        scwin.fn_save();
    }
};
scwin.img_close_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.img_publ_end_dd_onclick = function() {
    popUpCalendar2(edt_publ_end_dd);
};
scwin.txb_file_nm_onclick = function() {
    if (txb_file_nm.getValue() != "") {
        scwin.fn_filedown();
    }
};
scwin.gform_onload = function() {
    //showObj(txb_isurcd, false);	// 히든처리!
    // 패널라운드 처리
    $c.libRoundPanel.PanelToGroupBox(penel_1);
    scwin.fn_SetCode();

    // 가우스헤더 셋팅
    dts_file_save.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=IMPRSCHDLFILE_INOUT";
    dts_file_save.reset();

    // 파일: 가우스헤더 셋팅

    //dts_fileData.setDataHeader(); // W-Craft 주석처리 및 필요시 asis 파라미터 확인 
    dts_fileData.insertRow();
    scwin.fn_InitSearch();
};
